package com.yeyamo_mobile.api.culture_service.infrastructure.outbox;
import java.util.List;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class CultureOutboxRelay{private final CultureOutboxRepository repository;private final KafkaTemplate<String,String> kafka;private final String topic;public CultureOutboxRelay(CultureOutboxRepository r,KafkaTemplate<String,String> k,@Value("${culture.events.topic:culture.events}")String t){repository=r;kafka=k;topic=t;}@Scheduled(fixedDelayString="${culture.outbox.delay-ms:2000}")@Transactional public void relay(){List<CultureOutbox> events=repository.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc();for(CultureOutbox event:events){try{kafka.send(topic,event.getId().toString(),event.getPayload()).get();event.published();}catch(Exception e){event.failed(e.getMessage());}}}}
